module

public import Mathlib.Data.EReal.Basic
public import Mathlib.LinearAlgebra.Prod

@[expose] public section

universe u

namespace EReal



def effectiveDomain {E : Type u} (f : E → EReal) : Set E :=
  {x | f x < ⊤}


def epigraph {E : Type u} (f : E → EReal) : Set (E × ℝ) :=
  {p | f p.1 ≤ (p.2 : EReal)}



def IsPolyhedral {E : Type u} [AddCommGroup E] [Module ℝ E]
    (f : E → EReal) : Prop :=
  ∃ (r : ℕ) (a : Fin r → (E × ℝ) →ₗ[ℝ] ℝ) (b : Fin r → ℝ),
    epigraph f = {p | ∀ j, a j p ≤ b j}

end EReal
